insert_funcs = '''function parseLookthrough(item){const raw=String(item.lookthrough||'').trim(),parts=[];if(raw){raw.split(/[;\\n]+/).forEach(entry=>{const idx=entry.lastIndexOf(':');if(idx<1)return;const name=entry.slice(0,idx).trim(),weight=Number(entry.slice(idx+1).replace('%','').trim().replace(',','.'));if(name&&Number.isFinite(weight)&&weight>0)parts.push({name,weight:weight/100});});}else if(item.nature==='stock'&&String(item.name||'').trim()){parts.push({name:String(item.name).trim(),weight:1});}return parts;}function computeLookthrough(items,total){const map=new Map();let detailed=0;items.forEach(item=>{const parts=parseLookthrough(item);if(!parts.length)return;const sum=parts.reduce((s,x)=>s+x.weight,0),scale=sum>1?1/sum:1;detailed+=item.amount*Math.min(sum,1);parts.forEach(part=>{const amount=item.amount*part.weight*scale,key=part.name.toLowerCase().replace(/\\s+/g,' ').trim();if(!map.has(key))map.set(key,{name:part.name,amount:0,lines:new Set()});const rec=map.get(key);rec.amount+=amount;rec.lines.add(item.name||'Ligne sans nom');});});return{coverage:total?Math.min(detailed,total)/total:0,rows:[...map.values()].sort((a,b)=>b.amount-a.amount)};}'''
