calc_new = '''function dim(id){const raw=document.getElementById(id).value;return raw===''?null:Number(raw)}function calc(){const scores=Object.fromEntries(defs.map(([id])=>[id,dim(id)])),known=id=>scores[id]!==null,high=id=>known(id)&&scores[id]>=3,low=id=>known(id)&&scores[id]<=1,midplus=id=>known(id)&&scores[id]>=2,supports=defs.filter(([id])=>high(id)),frag=defs.filter(([id])=>low(id)),unknown=defs.filter(([id])=>!known(id)),run=n('runway'),need=n('transition');document.getElementById('supportCount').textContent=supports.length||'0';document.getElementById('fragileCount').textContent=frag.length||'0';document.getElementById('coverage').textContent=need?`${(run/need*100).toFixed(0)} % de votre durée cible`:(run?`${run.toFixed(1).replace('.',',')} mois`:'—');document.getElementById('supports').innerHTML=supports.length?supports.map(x=>`<span class="cap-tag">${x[1]}</span>`).join(''):'<span class="tool-muted">Aucun point d’appui fort ne ressort encore des faits saisis.</span>';document.getElementById('fragilities').innerHTML=frag.length?frag.map(x=>`<span class="cap-tag">${x[1]}</span>`).join(''):'<span class="tool-muted">Aucune fragilité forte ne ressort des dimensions renseignées.</span>';document.getElementById('unknowns').innerHTML=unknown.length?unknown.map(x=>`<span class="cap-tag">${x[1]}</span>`).join(''):'<span class="tool-muted">Toutes les dimensions ont été renseignées.</span>';const msg=[];if(high('stability')&&low('employability'))msg.push('Votre revenu actuel paraît solide mais les signaux de marché externes sont faibles : la stabilité du poste peut cacher une dépendance. Tester le marché avant d’en avoir besoin peut être plus important qu’une décision immédiate.');if(high('transfer')&&low('proof'))msg.push('Vos compétences semblent transférables mais les preuves visibles restent faibles. Avant d’ajouter une nouvelle formation, transformez l’expérience existante en résultats, références ou réalisations lisibles.');if(low('sustainability')&&midplus('employability'))msg.push('La soutenabilité est faible alors que le marché externe a déjà donné quelques signaux. La question centrale devient la qualité de la sortie, pas seulement la capacité théorique à rester.');if(low('options')&&val('goal')==='change')msg.push('Le projet de changement dépend encore d’un scénario unique ou peu testé. Ouvrir plusieurs portes avant de choisir une rupture augmente la réversibilité.');if(need&&run<need)msg.push(`Votre marge financière (${run.toFixed(1).replace('.',',')} mois) couvre moins que la durée de transition que vous souhaitez pouvoir absorber (${need.toFixed(1).replace('.',',')} mois). C’est votre propre écart de sécurité, pas un seuil universel.`);if(need&&run>=need)msg.push('La marge financière saisie couvre la durée de transition que vous avez vous-même retenue. Cela ne valide pas la décision, mais enlève une contrainte du scénario.');if(n('commute')>=90&&val('goal')!=='job')msg.push(`Vous avez saisi ${n('commute')} minutes de trajet quotidien. Ce temps mérite d’être traité comme une contrainte à part entière dans toute comparaison d’emploi.`);if(unknown.length)msg.push(`${unknown.length} dimension(s) restent inconnues ou non testées. Ne les transformez pas en moyenne implicite : choisissez lesquelles doivent être vérifiées avant la décision.`);if(!msg.length)msg.push('Aucune contradiction forte ne ressort des faits saisis. Regardez surtout la dimension la plus faible et demandez-vous si elle peut invalider votre scénario principal.');document.getElementById('reading').innerHTML=msg.map(x=>`<p>${x}</p>`).join('');const actions=[];const primary=links[val('goal')];actions.push(primary);if(low('proof')||low('transfer')||!known('proof')||!known('transfer'))actions.push(['dossiers/competences-qualification-employabilite.html','Clarifier compétences, preuves et employabilité','Distinguer ce que vous savez faire de ce que le marché peut réellement reconnaître.']);if(need&&run<need)actions.push(['dossiers/combien-epargne-avant-demissionner.html','Mesurer ma marge avant une rupture','Recalculer dépenses essentielles, durée de transition et réserve réellement disponible.']);if(n('commute')>=60)actions.push(['simulateur-cout-trajet-emploi.html','Mesurer le coût du trajet','Transformer le temps et le transport en coût comparable entre deux situations.']);if(low('sustainability'))actions.push(['dossiers/sante-travail-equilibre-vie-pro-perso.html','Examiner la soutenabilité du travail','Charge, horaires, récupération, santé et contraintes du poste.']);document.getElementById('actions').innerHTML=actions.slice(0,4).map(([href,t,x])=>`<a class="cap-action" href="${href}"><strong>${t} →</strong><span>${x}</span></a>`).join('')}function snapshot()'''
s = regex_once(s, calc_pattern, calc_new, 'professional calc', flags=re.S)
s = s.replace("employability:2,transfer:2,proof:2,network:2,stability:2,sustainability:2,options:2,reversibility:2", "employability:'',transfer:'',proof:'',network:'',stability:'',sustainability:'',options:'',reversibility:''")
